CSS = r'''
:root{--wine:#7b1024;--wine2:#4e0917;--deep:#350711;--gold:#caa45f;--bg:#f7f5f4;--ink:#211b1d;--muted:#746a6d;--line:#eee8e6;--green:#24934d;--shadow:0 8px 26px rgba(74,18,32,.08)}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;-webkit-font-smoothing:antialiased}a{color:inherit}button,input,select,textarea{font:inherit}.app-shell{min-height:100vh}
.sidebar{position:fixed;inset:0 auto 0 0;width:258px;padding:10px 9px 20px;background:radial-gradient(circle at 15% 10%,#9b1831 0,#751025 28%,#4c0b18 68%,#330711 100%);color:#fff;display:flex;flex-direction:column;z-index:50;overflow-y:auto;box-shadow:12px 0 34px rgba(48,5,16,.14)}
.brand-card{background:#fff;border-radius:14px;padding:14px 13px 12px;margin:0 2px 12px;min-height:216px;display:grid;place-items:center;box-shadow:0 10px 26px rgba(0,0,0,.12)}.brand-card img{display:block;width:100%;height:188px;object-fit:contain}.side-nav{display:flex;flex-direction:column;gap:4px}.nav-link{display:flex;align-items:center;gap:13px;min-height:45px;padding:9px 14px;border-radius:10px;color:#fff;text-decoration:none;font-size:14px;font-weight:650;transition:.18s}.nav-link:hover,.nav-link.active{background:rgba(196,27,58,.7)}.nav-icon{width:23px;height:23px;display:grid;place-items:center;font-size:17px}.nav-link.logout{margin-top:10px}.sidebar-art{margin-top:auto;min-height:112px;position:relative;overflow:hidden}.sidebar-art:before,.sidebar-art:after{content:"";position:absolute;border-radius:50% 50% 0 50%;border:2px solid var(--gold);opacity:.88;transform:rotate(34deg)}.sidebar-art:before{width:52px;height:19px;right:26px;bottom:28px}.sidebar-art:after{width:40px;height:15px;right:55px;bottom:54px}.sidebar-wave{position:absolute;left:-16px;right:-16px;bottom:3px;height:32px;border-radius:50% 50% 0 0;background:linear-gradient(170deg,transparent 35%,var(--gold) 36% 43%,#fff 44% 55%,transparent 56%)}
.main-area{margin-left:258px;min-height:100vh}.topbar{height:94px;background:rgba(255,255,255,.97);border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 30px;position:sticky;top:0;z-index:30}.title-block{display:flex;align-items:center;gap:15px}.mini-mark{width:48px;height:48px;border:2px solid var(--wine);border-radius:12px;color:var(--wine);display:grid;place-items:center;font-size:24px;font-weight:900}.title-copy strong{display:block;color:var(--wine);font-size:22px}.title-copy small{display:block;font-size:14px;margin-top:1px}.top-meta{display:flex;align-items:center;gap:24px}.cycle{display:flex;align-items:center;gap:8px;font-size:14px}.bell{position:relative;color:var(--wine);font-size:20px}.bell:after{content:"3";position:absolute;right:-9px;top:-9px;width:17px;height:17px;border-radius:50%;display:grid;place-items:center;background:#c51631;color:#fff;font-size:10px;font-weight:800}.admin-box{display:flex;align-items:center;gap:10px}.avatar{width:42px;height:42px;border-radius:50%;background:linear-gradient(145deg,#9c1b33,#53101e);color:#fff;display:grid;place-items:center;font-weight:850}.admin-copy b{display:block;font-size:14px}.admin-copy small{display:block;color:var(--muted);font-size:12px}.drawer-toggle{display:none;width:42px;height:42px;padding:0;background:transparent;color:var(--wine);border:1px solid var(--line);box-shadow:none}
.wrap{max-width:1420px;margin:0 auto;padding:22px 24px 30px}.dashboard-grid{display:grid;grid-template-columns:minmax(0,1fr) 310px;gap:16px}.dashboard-main,.right-rail{min-width:0}.panel,.card{background:#fff;border:1px solid var(--line);border-radius:14px;box-shadow:var(--shadow)}.card{padding:18px;margin-bottom:16px}.panel{padding:18px;margin-bottom:14px}
.hero-panel{min-height:220px;padding:26px 28px;display:grid;grid-template-columns:minmax(0,1fr) 360px;gap:12px;align-items:center;position:relative;overflow:hidden}.hero-panel:after{content:"";position:absolute;width:190px;height:190px;border:30px solid rgba(202,164,95,.08);border-radius:50%;right:165px;bottom:-130px}.hero-copy{position:relative;z-index:2}.hero-copy h1{margin:0;color:var(--wine);font-size:28px;line-height:1.18}.hero-rule{display:block;width:34px;height:3px;border-radius:10px;background:var(--gold);margin:16px 0 18px}.hero-copy p{max-width:610px;margin:0;color:#3d3437;line-height:1.65;font-size:14px}.hero-brand{display:grid;grid-template-columns:155px 1fr;gap:18px;align-items:center;position:relative;z-index:2}.hero-brand img{width:155px;height:155px;object-fit:contain}.quote-mark{font-size:54px;line-height:.6;color:var(--gold);font-family:Georgia,serif}.quote-text{font-size:15px;line-height:1.6;margin:8px 0}.quote-author{font-weight:800;color:var(--wine)}
.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:14px 0}.stat-card{background:#fff;border:1px solid var(--line);border-radius:13px;padding:17px 16px;min-height:112px;display:flex;align-items:center;gap:14px;box-shadow:var(--shadow)}.stat-icon{flex:0 0 52px;width:52px;height:52px;border-radius:50%;display:grid;place-items:center;background:var(--wine);color:#fff;font-size:23px}.stat-icon.gold{background:var(--gold)}.stat-label{font-size:13px}.kpi{font-size:31px;font-weight:850;line-height:1.05;margin:3px 0}.stat-sub{font-size:11px;color:var(--wine);font-weight:750}.stat-sub.gold{color:#b07f2d}.muted{color:var(--muted);font-size:13px}h1{font-size:28px}h2{margin:0 0 14px;font-size:15px}
.quick-panel{padding:18px 18px 14px}.quick{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:14px}.quick a{min-height:112px;border:1px solid #f0ecea;border-radius:12px;text-decoration:none;background:#fff;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:10px 7px;text-align:center;gap:9px;font-size:12px;box-shadow:0 5px 16px rgba(50,20,28,.04);transition:.18s}.quick a:hover{transform:translateY(-2px);border-color:#dcc9cd}.quick-icon{font-size:29px;color:var(--wine);line-height:1}.quick a:nth-child(even) .quick-icon{color:var(--gold)}
.analytics-row{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(280px,.8fr);gap:14px}.analytics-card{min-height:250px}.analytics-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:10px}.chart-wrap{height:190px}.line-chart{width:100%;height:160px;overflow:visible}.line-chart line{stroke:#ece7e5;stroke-width:1}.line-chart polyline{fill:none;stroke:var(--wine);stroke-width:4;stroke-linecap:round;stroke-linejoin:round}.line-chart circle{fill:var(--wine)}.chart-labels{display:flex;justify-content:space-between;color:#5f5558;font-size:11px;padding:0 12px}.empty-chart{height:175px;display:grid;place-items:center;color:var(--muted);text-align:center}.ring-wrap{display:flex;align-items:center;justify-content:center;gap:22px;height:190px}.ring{width:140px;height:140px;border-radius:50%;display:grid;place-items:center;background:conic-gradient(var(--wine) var(--pct),#efecea 0);position:relative}.ring:after{content:"";position:absolute;width:106px;height:106px;background:#fff;border-radius:50%}.ring-copy{position:relative;z-index:2;text-align:center}.ring-copy b{display:block;font-size:28px;color:var(--wine)}.ring-copy span{font-size:11px}.trend{color:var(--green);font-weight:850;font-size:18px}.trend small{display:block;color:var(--muted);font-size:11px;font-weight:500;margin-top:4px}
.calendar-card{padding:18px}.calendar-title{display:flex;align-items:center;gap:8px;margin-bottom:18px;font-weight:800}.calendar-head{display:flex;align-items:center;justify-content:space-between;color:var(--wine);margin-bottom:12px}.ghost-btn{width:31px;height:31px;padding:0;border:0;background:transparent;color:var(--wine);box-shadow:none;font-size:24px}.cal-week,.cal-grid{display:grid;grid-template-columns:repeat(7,1fr);text-align:center}.cal-week{font-size:11px;color:#5f5659;margin-bottom:7px}.cal-day{height:34px;display:grid;place-items:center;font-size:12px;border-radius:50%;justify-self:center;width:34px}.cal-day.today{background:var(--wine);color:#fff}.muted-day{opacity:.2}.event{display:grid;grid-template-columns:10px 1fr;gap:9px;padding:9px 0}.event-dot{width:9px;height:9px;border-radius:50%;background:var(--wine);margin-top:5px}.event:nth-child(even) .event-dot{background:var(--gold)}.event b{font-size:12px;display:block}.event small{color:var(--muted);font-size:11px}.recent-list{display:flex;flex-direction:column}.recent-item{display:grid;grid-template-columns:40px 1fr auto;align-items:center;gap:10px;padding:9px 0;border-bottom:1px solid #f4efed}.recent-item:last-child{border:0}.recent-badge{width:38px;height:38px;border-radius:50%;display:grid;place-items:center;background:var(--wine);color:#fff}.recent-item:nth-child(even) .recent-badge{background:var(--gold)}.recent-item b{font-size:12px}.recent-item small,.recent-time{font-size:11px;color:var(--muted)}
.page-head{margin:0 0 16px}.page-head h1{margin:0 0 5px;color:var(--wine)}.page-head p{margin:0;color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:13px}.wide{grid-column:1/-1}.scroll{overflow:auto;border-radius:10px}table{width:100%;border-collapse:collapse;min-width:650px}th,td{padding:12px 11px;border-bottom:1px solid var(--line);text-align:left;font-size:13px}th{font-size:11px;text-transform:uppercase;letter-spacing:.45px;color:#675d60;background:#faf8f7}tbody tr:hover td{background:#fcfaf9}label{font-size:12px;font-weight:750;color:#50474a;display:block}label input,label select,label textarea{margin-top:6px}input,select,textarea,button{width:100%;padding:11px 12px;border:1px solid #dcd4d1;border-radius:9px;background:#fff;color:var(--ink);outline:none}textarea{min-height:90px;resize:vertical}input:focus,select:focus,textarea:focus{border-color:#a33b50;box-shadow:0 0 0 3px rgba(123,16,36,.08)}button{border:0;background:var(--wine);color:#fff;font-weight:800;cursor:pointer;box-shadow:0 6px 15px rgba(123,16,36,.16)}.alert{padding:12px 14px;border-radius:10px;background:#fff2d9;border:1px solid #ead6ac;margin-bottom:14px}.danger{background:#fde8e8;border-color:#efc0c0}.footer{display:flex;justify-content:space-between;gap:18px;border-top:1px solid #dcc6ca;margin-top:8px;padding:16px 6px 4px;font-size:11px;color:#554b4e}.footer strong{color:var(--wine)}
.login-layout{min-height:100vh;display:grid;grid-template-columns:minmax(340px,45%) 1fr;background:#fff}.login-brand{background:radial-gradient(circle at 15% 10%,#951a31,#651023 55%,#3c0914);display:flex;align-items:center;justify-content:center;padding:40px}.login-logo-box{background:#fff;border-radius:22px;padding:24px;width:min(430px,90%);box-shadow:0 24px 70px rgba(0,0,0,.2)}.login-logo-box img{display:block;width:100%;max-height:430px;object-fit:contain}.login-pane{display:grid;place-items:center;padding:32px;background:#faf8f7}.login-pane-inner{width:min(500px,100%)}.login-pane .card{padding:28px;border-radius:18px}.login-pane h1{color:var(--wine)}.mobile-top,.mobile-brand,.bottom-nav{display:none}.overlay{display:none}
@media(max-width:1120px){.dashboard-grid{grid-template-columns:1fr}.right-rail{display:grid;grid-template-columns:1fr 1fr;gap:14px}.right-rail .panel{margin:0}.hero-panel{grid-template-columns:1fr 300px}.quick{grid-template-columns:repeat(3,1fr)}.stats{grid-template-columns:repeat(2,1fr)}}
@media(max-width:900px){.sidebar{transform:translateX(-105%);transition:.24s}.sidebar.open{transform:translateX(0)}.overlay.open{display:block;position:fixed;inset:0;background:#0006;z-index:40}.main-area{margin-left:0}.drawer-toggle{display:grid;place-items:center}.topbar{padding:0 18px}.wrap{padding:18px}.hero-panel{grid-template-columns:1fr}.hero-brand{grid-template-columns:120px 1fr}.hero-brand img{width:120px;height:120px}.analytics-row{grid-template-columns:1fr}}
@media(max-width:720px){body{padding-bottom:68px}.sidebar,.overlay,.topbar{display:none!important}.main-area{margin:0}.mobile-top{position:sticky;top:0;z-index:35;height:54px;background:linear-gradient(135deg,var(--wine),#620b1e);display:flex;align-items:center;justify-content:space-between;padding:0 15px;color:#fff}.mobile-brand{display:block;margin:12px 12px 8px;background:#fff;border:1px solid var(--line);border-radius:12px;padding:10px;box-shadow:var(--shadow)}.mobile-brand img{display:block;width:100%;height:160px;object-fit:contain}.wrap{padding:8px 12px 14px}.dashboard-grid{display:block}.right-rail{display:block}.hero-panel{min-height:auto;padding:16px 14px;display:block}.hero-brand{display:none}.hero-copy h1{font-size:20px}.hero-rule{margin:10px 0 12px}.hero-copy p{font-size:11px}.stats{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:10px 0}.stat-card{min-height:82px;padding:10px 9px;gap:8px}.stat-icon{width:38px;height:38px;flex-basis:38px;font-size:17px}.stat-label{font-size:10px}.kpi{font-size:20px}.stat-sub{font-size:8px}.quick-panel{padding:13px 10px}.quick{grid-template-columns:repeat(4,82px);gap:7px;overflow-x:auto}.quick a{min-height:82px;font-size:9px}.quick-icon{font-size:21px}.analytics-row{display:block}.panel,.card{border-radius:11px}.footer{display:none}.bottom-nav{position:fixed;left:0;right:0;bottom:0;z-index:45;height:64px;padding-bottom:env(safe-area-inset-bottom);background:linear-gradient(135deg,var(--wine),#5f091b);display:grid;grid-template-columns:repeat(5,1fr);box-shadow:0 -4px 18px #3b09154a}.bottom-nav a{color:#fff;text-decoration:none;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;font-size:9px}.bottom-nav i{font-style:normal;font-size:18px}.bottom-nav a.active{background:#ffffff14}.login-layout{grid-template-columns:1fr}.login-brand{padding:20px;min-height:280px}.login-logo-box{padding:12px;width:min(310px,90%)}.login-logo-box img{max-height:240px}.login-pane{padding:18px 14px}.login-pane .card{padding:20px}.grid{grid-template-columns:1fr}.calendar-card{padding:14px}.cal-day{width:31px;height:31px;font-size:11px}.ring-wrap{height:160px}.ring{width:120px;height:120px}.ring:after{width:90px;height:90px}}
@media(max-width:420px){.mobile-brand img{height:145px}.recent-item{grid-template-columns:34px 1fr}.recent-time{display:none}.recent-badge{width:32px;height:32px}}
'''